on conflict (id) do nothing;

on conflict (weekday) do nothing;

values ('36edc47f-8ea4-5eeb-940f-70b6ff67abc5', 'general', 0, 'therapy', '{"ru": "Общая стоматология", "kk": "Жалпы стоматология", "en": "General Dentistry"}'::jsonb, '{"ru": "Осмотр, диагностика и лечение — основа здоровой улыбки.", "kk": "Тексеру, диагностика және емдеу — сау күлкінің негізі.", "en": "Examinations, diagnostics and treatment — the foundation of a healthy smile."}'::jsonb, '{"ru": "Мы начинаем с внимательного осмотра и разговора: что вас беспокоит, какие ожидания, какой опыт лечения уже был. План лечения составляется только после диагностики и обсуждается с вами заранее.", "kk": "Біз мұқият тексеруден және әңгімеден бастаймыз: сізді не мазалайды, қандай күтулеріңіз бар, бұрын қандай ем алдыңыз. Емдеу жоспары тек диагностикадан кейін құрылып, сізбен алдын ала талқыланады.", "en": "We begin with a careful examination and a conversation: what concerns you, what you expect, and what treatment you have had before. A treatment plan is drawn up only after diagnostics and agreed with you in advance."}'::jsonb, '[{"ru": "Консультация и сбор жалоб", "kk": "Кеңес және шағымдарды тыңдау", "en": "Consultation and history"}, {"ru": "Осмотр и диагностика", "kk": "Тексеру және диагностика", "en": "Examination and diagnostics"}, {"ru": "План лечения и его стоимость", "kk": "Емдеу жоспары және оның құны", "en": "Treatment plan and cost estimate"}, {"ru": "Лечение и рекомендации", "kk": "Емдеу және ұсыныстар", "en": "Treatment and aftercare advice"}]'::jsonb, '[{"ru": "Возьмите снимки и выписки, если они есть.", "kk": "Бар болса, рентген суреттері мен анықтамаларды ала келіңіз.", "en": "Bring any previous X-rays or records you have."}, {"ru": "Сообщите врачу о принимаемых лекарствах и аллергиях.", "kk": "Қабылдап жүрген дәрілеріңіз бен аллергияңыз туралы дәрігерге айтыңыз.", "en": "Tell the dentist about any medication or allergies."}]'::jsonb, 60, '{"ru": "45–60 мин", "kk": "45–60 мин", "en": "45–60 min"}'::jsonb, 'assets/images/photos/exam-mirror.webp', '{"ru": "Осмотр зубов стоматологическим зеркалом", "kk": "Тісті стоматологиялық айнамен тексеру", "en": "Dental examination with a mouth mirror"}'::jsonb)
on conflict (slug) do nothing;
values ('3a86544b-b6b9-5ba7-8d86-a8b99cfe18c6', 'implants', 1, 'surgery', '{"ru": "Имплантация зубов", "kk": "Тіс имплантациясы", "en": "Dental Implants"}'::jsonb, '{"ru": "Восстановление утраченных зубов с тщательным планированием.", "kk": "Жоғалған тістерді мұқият жоспарлаумен қалпына келтіру.", "en": "Replacing missing teeth with careful, step-by-step planning."}'::jsonb, '{"ru": "Имплантация — многоэтапное лечение. Возможность, сроки и метод определяет врач после обследования и снимков. Мы подробно объясняем каждый этап и альтернативы.", "kk": "Имплантация — бірнеше кезеңнен тұратын ем. Мүмкіндігін, мерзімі мен әдісін дәрігер тексеру мен суреттерден кейін анықтайды. Әр кезеңді және балама жолдарды толық түсіндіреміз.", "en": "Implant treatment happens in several stages. Suitability, timing and technique are decided by the dentist after an examination and imaging. We explain every stage and the alternatives."}'::jsonb, '[{"ru": "Консультация и обследование", "kk": "Кеңес және тексеру", "en": "Consultation and assessment"}, {"ru": "Цифровое планирование", "kk": "Цифрлық жоспарлау", "en": "Digital planning"}, {"ru": "Установка импланта", "kk": "Имплантты орнату", "en": "Implant placement"}, {"ru": "Протезирование и контроль", "kk": "Протездеу және бақылау", "en": "Restoration and follow-up"}]'::jsonb, '[{"ru": "Пройдите обследование, назначенное врачом.", "kk": "Дәрігер тағайындаған тексеруден өтіңіз.", "en": "Complete the assessment your dentist recommends."}, {"ru": "Обсудите с врачом хронические заболевания.", "kk": "Созылмалы ауруларыңызды дәрігермен талқылаңыз.", "en": "Discuss any chronic conditions with your dentist."}]'::jsonb, 90, '{"ru": "Несколько визитов", "kk": "Бірнеше келу", "en": "Several visits"}'::jsonb, 'assets/images/photos/implant-hand.webp', '{"ru": "Дентальный имплант и коронка в руке врача", "kk": "Дәрігер қолындағы дентальды имплант пен коронка", "en": "A dental implant and crown held by a gloved hand"}'::jsonb)
on conflict (slug) do nothing;
values ('e2b5bf7e-2c11-5e50-91ba-c74c6cf375e7', 'orthodontics', 2, 'orthodontics', '{"ru": "Ортодонтия и брекеты", "kk": "Ортодонтия және брекеттер", "en": "Orthodontics & Braces"}'::jsonb, '{"ru": "Брекеты и элайнеры для ровной улыбки и правильного прикуса.", "kk": "Түзу күлкі мен дұрыс тістесу үшін брекеттер мен элайнерлер.", "en": "Braces and aligners for straighter teeth and a healthier bite."}'::jsonb, '{"ru": "Ортодонтическое лечение подбирается индивидуально: брекет-системы или элайнеры. Врач оценивает прикус, показывает план и объясняет, как будет проходить лечение.", "kk": "Ортодонтиялық ем жеке таңдалады: брекет-жүйелер немесе элайнерлер. Дәрігер тістесуді бағалап, жоспарды көрсетеді және емнің қалай өтетінін түсіндіреді.", "en": "Orthodontic treatment is chosen individually — braces or clear aligners. The orthodontist assesses your bite, shows you the plan and explains how treatment will progress."}'::jsonb, '[{"ru": "Консультация ортодонта", "kk": "Ортодонт кеңесі", "en": "Orthodontic consultation"}, {"ru": "Слепки или сканирование", "kk": "Қалып алу немесе сканерлеу", "en": "Impressions or digital scan"}, {"ru": "План и выбор системы", "kk": "Жоспар және жүйені таңдау", "en": "Plan and choice of system"}, {"ru": "Лечение и регулярный контроль", "kk": "Емдеу және тұрақты бақылау", "en": "Treatment and regular check-ups"}]'::jsonb, '[{"ru": "Перед установкой рекомендуется профессиональная гигиена.", "kk": "Орнатар алдында кәсіби гигиена ұсынылады.", "en": "A professional clean is recommended beforehand."}]'::jsonb, 60, '{"ru": "Индивидуально", "kk": "Жеке", "en": "Individual"}'::jsonb, 'assets/images/photos/aligners.webp', '{"ru": "Прозрачные элайнеры и футляр в руках", "kk": "Қолдағы мөлдір элайнерлер мен қорап", "en": "Hands holding clear aligners and a case"}'::jsonb)
on conflict (slug) do nothing;
values ('8dd5f3c7-793b-5a92-b787-c55cfb7d35fb', 'cosmetic', 3, 'aesthetics', '{"ru": "Эстетическая стоматология", "kk": "Эстетикалық стоматология", "en": "Cosmetic Dentistry"}'::jsonb, '{"ru": "Форма, цвет и пропорции улыбки — в гармонии с лицом.", "kk": "Күлкінің пішіні, түсі мен пропорциясы — бет әлпетімен үйлесімде.", "en": "Shape, shade and proportion of a smile — in harmony with your face."}'::jsonb, '{"ru": "Эстетическое лечение начинается с анализа улыбки и обсуждения ваших пожеланий. Врач предлагает варианты и честно говорит о возможностях и ограничениях каждого.", "kk": "Эстетикалық ем күлкіні талдаудан және тілектеріңізді талқылаудан басталады. Дәрігер нұсқаларды ұсынып, әрқайсысының мүмкіндіктері мен шектеулері туралы ашық айтады.", "en": "Cosmetic treatment starts with a smile analysis and a conversation about your wishes. Your dentist suggests options and is honest about what each can and cannot achieve."}'::jsonb, '[{"ru": "Анализ улыбки", "kk": "Күлкіні талдау", "en": "Smile analysis"}, {"ru": "Обсуждение вариантов", "kk": "Нұсқаларды талқылау", "en": "Discussing options"}, {"ru": "Пробная модель (при необходимости)", "kk": "Сынама модель (қажет болса)", "en": "Mock-up (if needed)"}, {"ru": "Лечение и рекомендации", "kk": "Емдеу және ұсыныстар", "en": "Treatment and aftercare"}]'::jsonb, '[{"ru": "Подумайте, что именно вы хотели бы изменить.", "kk": "Нақты нені өзгерткіңіз келетінін ойластырыңыз.", "en": "Think about what exactly you would like to change."}]'::jsonb, 60, '{"ru": "От 1 визита", "kk": "1 келуден бастап", "en": "From 1 visit"}'::jsonb, 'assets/images/photos/smile-closeup.webp', '{"ru": "Крупный план улыбки", "kk": "Күлкінің жақын көрінісі", "en": "Close-up of a smile"}'::jsonb)
on conflict (slug) do nothing;
values ('ad792652-2805-5eed-afe5-61821a371771', 'cleaning', 4, 'prevention', '{"ru": "Профессиональная гигиена", "kk": "Кәсіби гигиена", "en": "Professional Cleaning"}'::jsonb, '{"ru": "Бережное удаление налёта и зубного камня, советы по уходу.", "kk": "Тіс қағы мен тас шөгіндісін ұқыпты тазалау, күтім бойынша кеңес.", "en": "Gentle removal of plaque and tartar, with personal care advice."}'::jsonb, '{"ru": "Регулярная профессиональная гигиена помогает поддерживать здоровье зубов и дёсен. Гигиенист подберёт средства ухода и покажет технику чистки.", "kk": "Тұрақты кәсіби гигиена тіс пен қызыл иектің саулығын сақтауға көмектеседі. Гигиенист күтім құралдарын таңдап, тазалау әдісін көрсетеді.", "en": "Regular professional cleaning helps keep teeth and gums healthy. The hygienist will recommend care products and show you brushing technique."}'::jsonb, '[{"ru": "Осмотр полости рта", "kk": "Ауыз қуысын тексеру", "en": "Oral check"}, {"ru": "Удаление зубного камня", "kk": "Тіс тасын кетіру", "en": "Tartar removal"}, {"ru": "Полировка", "kk": "Жылтырату", "en": "Polishing"}, {"ru": "Рекомендации по уходу", "kk": "Күтім бойынша ұсыныстар", "en": "Home-care advice"}]'::jsonb, '[{"ru": "Специальной подготовки не требуется.", "kk": "Арнайы дайындық қажет емес.", "en": "No special preparation is needed."}]'::jsonb, 60, '{"ru": "60 мин", "kk": "60 мин", "en": "60 min"}'::jsonb, 'assets/images/photos/mirror-explorer.webp', '{"ru": "Стоматологическое зеркало и зонд на белом фоне", "kk": "Ақ фондағы стоматологиялық айна мен зонд", "en": "Dental mirror and explorer on a white surface"}'::jsonb)
on conflict (slug) do nothing;
values ('393a787f-f26b-580c-b6f1-d1cd6f6fa6d2', 'whitening', 5, 'aesthetics', '{"ru": "Отбеливание зубов", "kk": "Тісті ағарту", "en": "Teeth Whitening"}'::jsonb, '{"ru": "Осветление эмали под контролем врача.", "kk": "Дәрігер бақылауымен эмальді ағарту.", "en": "Dentist-supervised brightening of natural enamel."}'::jsonb, '{"ru": "Перед отбеливанием врач оценивает состояние зубов и проводит гигиену. Результат индивидуален и зависит от исходного цвета эмали — врач обсудит реалистичные ожидания.", "kk": "Ағарту алдында дәрігер тістің жағдайын бағалап, гигиена жүргізеді. Нәтиже жеке және эмальдің бастапқы түсіне байланысты — дәрігер шынайы күтулерді талқылайды.", "en": "Before whitening, the dentist checks your teeth and performs a clean. Results vary with your natural enamel shade — your dentist will discuss realistic expectations."}'::jsonb, '[{"ru": "Осмотр и гигиена", "kk": "Тексеру және гигиена", "en": "Check-up and cleaning"}, {"ru": "Определение исходного оттенка", "kk": "Бастапқы реңкті анықтау", "en": "Recording your starting shade"}, {"ru": "Процедура отбеливания", "kk": "Ағарту процедурасы", "en": "Whitening procedure"}, {"ru": "Рекомендации после", "kk": "Кейінгі ұсыныстар", "en": "Aftercare advice"}]'::jsonb, '[{"ru": "За 1–2 недели рекомендуется профгигиена.", "kk": "1–2 апта бұрын кәсіби гигиена ұсынылады.", "en": "A professional clean 1–2 weeks before is recommended."}]'::jsonb, 90, '{"ru": "60–90 мин", "kk": "60–90 мин", "en": "60–90 min"}'::jsonb, 'assets/images/photos/smile-portrait.webp', '{"ru": "Улыбающаяся женщина", "kk": "Күлімсіреген әйел", "en": "A smiling woman"}'::jsonb)
on conflict (slug) do nothing;
values ('5440f6a1-e22a-5b96-8ab7-d0e6f3163188', 'veneers', 6, 'aesthetics', '{"ru": "Виниры", "kk": "Винирлер", "en": "Veneers"}'::jsonb, '{"ru": "Тонкие керамические накладки для формы и цвета.", "kk": "Пішін мен түс үшін жұқа керамикалық қаптамалар.", "en": "Thin ceramic shells that refine shape and shade."}'::jsonb, '{"ru": "Виниры подходят не всем. Решение принимается после диагностики, анализа улыбки и обсуждения альтернатив. Мы показываем будущий результат на пробной модели до начала работы.", "kk": "Винирлер барлығына сәйкес келе бермейді. Шешім диагностика, күлкіні талдау және балама жолдарды талқылаудан кейін қабылданады. Жұмыс басталмас бұрын болашақ нәтижені сынама модельде көрсетеміз.", "en": "Veneers are not right for everyone. The decision follows diagnostics, smile analysis and a discussion of alternatives. We preview the outcome on a mock-up before any work begins."}'::jsonb, '[{"ru": "Диагностика и анализ улыбки", "kk": "Диагностика және күлкіні талдау", "en": "Diagnostics and smile analysis"}, {"ru": "Пробная модель", "kk": "Сынама модель", "en": "Mock-up"}, {"ru": "Подготовка и изготовление", "kk": "Дайындау және жасау", "en": "Preparation and fabrication"}, {"ru": "Фиксация и контроль", "kk": "Бекіту және бақылау", "en": "Fitting and follow-up"}]'::jsonb, '[{"ru": "Сначала необходимо вылечить кариес и дёсны.", "kk": "Алдымен тісжегі мен қызыл иекті емдеу қажет.", "en": "Any decay or gum problems must be treated first."}]'::jsonb, 90, '{"ru": "2–3 визита", "kk": "2–3 келу", "en": "2–3 visits"}'::jsonb, 'assets/images/photos/implant-model.webp', '{"ru": "Модели зубов и коронок", "kk": "Тіс және коронка модельдері", "en": "Models of teeth and crowns"}'::jsonb)
on conflict (slug) do nothing;
values ('2aef4372-4185-593c-8828-ab29ac006f48', 'pediatric', 7, 'kids', '{"ru": "Детская стоматология", "kk": "Балалар стоматологиясы", "en": "Pediatric Dentistry"}'::jsonb, '{"ru": "Спокойные визиты, которые формируют доверие к врачу.", "kk": "Дәрігерге сенім қалыптастыратын тыныш қабылдаулар.", "en": "Calm visits that help children trust the dentist."}'::jsonb, '{"ru": "Первый визит — знакомство: ребёнок осматривается в кабинете, а врач объясняет всё простыми словами. Мы не торопимся и всегда держим родителей в курсе.", "kk": "Алғашқы келу — танысу: бала кабинетпен танысады, ал дәрігер бәрін қарапайым сөзбен түсіндіреді. Біз асықпаймыз және ата-аналарды үнемі хабардар етеміз.", "en": "The first visit is an introduction: your child gets to know the room while the dentist explains everything in simple words. We never rush, and parents are always kept informed."}'::jsonb, '[{"ru": "Знакомство", "kk": "Танысу", "en": "Getting acquainted"}, {"ru": "Бережный осмотр", "kk": "Ұқыпты тексеру", "en": "Gentle check-up"}, {"ru": "Рекомендации родителям", "kk": "Ата-аналарға ұсыныстар", "en": "Advice for parents"}, {"ru": "План профилактики", "kk": "Профилактика жоспары", "en": "Prevention plan"}]'::jsonb, '[{"ru": "Расскажите ребёнку о визите спокойно и без страшилок.", "kk": "Балаға келу туралы сабырмен, қорқытпай айтыңыз.", "en": "Talk to your child about the visit calmly and positively."}]'::jsonb, 45, '{"ru": "30–45 мин", "kk": "30–45 мин", "en": "30–45 min"}'::jsonb, 'assets/images/photos/kids-brushing.webp', '{"ru": "Дети чистят зубы", "kk": "Балалар тісін тазалап жатыр", "en": "Children brushing their teeth"}'::jsonb)
on conflict (slug) do nothing;

